package mx.com.mesaregia.pagos.application.service.impl;
import mx.com.mesaregia.pagos.api.response.*; import mx.com.mesaregia.pagos.application.service.PagoQueryService; import mx.com.mesaregia.pagos.domain.enums.*; import mx.com.mesaregia.pagos.mapper.PagoMapper; import mx.com.mesaregia.pagos.repository.*; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate;
@Service public class PagoQueryServiceImpl implements PagoQueryService {private final MovimientoCuentaRepository repo;private final PagoMapper mapper;public PagoQueryServiceImpl(MovimientoCuentaRepository r,PagoMapper m){repo=r;mapper=m;}@Override @Transactional(readOnly=true) public PageResponse<MovimientoPagoResponse> buscar(String f,Integer v,String c,LocalDate d,LocalDate h,MetodoPago mp,TipoRegistroPago t,EstadoCuentaCobro e,Long u,Pageable p){var page=repo.findAll(MovimientoCuentaSpecifications.pagos(f,v,c,d,h,mp,t,e,u),p).map(mapper::movimiento);return PageResponse.of(page);}}
